// Generated by ts-rs from the Rust types in gitvur-schema and gitvur-app.
// Do not edit by hand: run `pnpm gen:types` from app/.

export type Manifest = {
/**
 * Always [`crate::SCHEMA_VERSION`].
 */
schemaVersion: string, projectName: string,
/**
 * Short (7-character) SHA of `HEAD`, or [`crate::UNCOMMITTED`] when the repository
 * is not a Git checkout or has no commits.
 */
commitSha: string,
/**
 * RFC 3339 UTC timestamp. The only non-deterministic field in the contract.
 */
generatedAt: string, extractor: ExtractorInfo, languages: Array<Language>, };

export type ExtractorInfo = { name: string, version: string, };

export type Language = "c" | "go" | "python" | "typescript";

export type Structure = { nodes: Array<Node>, edges: Array<Edge>,
/**
 * Calls with two or more in-repo candidate targets.
 */
unresolvedCalls: Array<UnresolvedCall>,
/**
 * Deterministic entry points; omitted when empty to preserve v0.2 canonical bytes.
 */
entryPoints?: Array<EntryPoint>, };

export type Node = { id: string, type: NodeType, name: string,
/**
 * Absent only on the project node.
 */
parentId?: string,
/**
 * Absent only on the project node.
 */
source?: SourceRange,
/**
 * `sha256:<64 lowercase hex>`. Absent only on the project node.
 */
contentHash?: string, };

export type NodeType = "project" | "file" | "class" | "function";

export type UnresolvedCall = {
/**
 * The calling function.
 */
from: string,
/**
 * The called name as written at the call site (the last segment for `a.b.name()`).
 */
name: string, evidence: Evidence,
/**
 * Every in-repo node the call could target; always two or more.
 */
candidates: Array<string>, };

export type Trace = { start: string,
/**
 * Occurrence IDs, not source node IDs.
 */
roots: Array<string>,
/**
 * Breadth-first allocation order. Children refer to occurrence IDs in this array.
 */
nodes: Array<TraceNode>, truncated: boolean, hiddenRoots: number,
/**
 * Unknown start IDs are explicit failures, not successful empty traces.
 */
error: string | null, };

export type TraceNode = { id: string, kind: TraceKind, node: string | null, name: string, depth: number, children: Array<string>,
/**
 * First occurrence ID, for ref/cycle stubs only.
 */
reference: string | null, candidates: Array<string>, evidence: Evidence | null, truncated: boolean,
/**
 * Immediate outgoing occurrences omitted here, not transitive descendants.
 */
hiddenChildren: number, };

export type TraceKind = "node" | "ref" | "cycle" | "ambiguous";

export type EntryPoint = { id: string, kind: EntryKind, name: string,
/**
 * A resolved node ID, or null when configuration names code outside the index.
 */
target: string | null, raw?: string, calls: Array<string>,
/**
 * Optional at deserialization so validation can diagnose missing AI evidence.
 */
evidence?: Evidence, provenance: Provenance, };

export type EntryKind = "cli-command" | "console-script" | "event-handler" | "http-route" | "job" | "main-function" | "main-guard" | "npm-script" | "other" | "package-bin" | "package-main" | "test" | "top-level-call";

export type Flow = { id: string, name: string, description: string, entryPoint: string,
/**
 * Reading order: canonicalization must not sort or deduplicate steps.
 */
steps: Array<FlowStep>, transitions: Array<FlowTransition>, };

export type FlowStep = { id: string, node: string, label: string, basedOnHash: string, };

export type FlowTransition = { from: string, to: string, kind: TransitionKind, label?: string, provenance: Provenance, evidence?: Evidence, };

export type TransitionKind = "async" | "branch" | "call" | "event" | "return";

export type FlowStatus = { id: string, status: FlowState, staleSteps: Array<string>, };

export type FlowState = "broken" | "current" | "stale";

export type Edge = { from: string, to: string, type: EdgeType, provenance: Provenance, evidence: Evidence,
/**
 * Free-text explanation; written by the agent for `ai` edges.
 */
note?: string, };

export type EdgeType = "calls" | "depends_on" | "imports" | "references";

export type Provenance = "syntactic" | "semantic" | "ai";

export type Evidence = {
/**
 * Path relative to the repository root, `/`-separated.
 */
file: string,
/**
 * 1-based line number.
 */
line: number, };

export type SourceRange = {
/**
 * Path relative to the repository root, `/`-separated.
 */
file: string, startLine: number, endLine: number, };

export type Architecture = { version: number, summary: string, components: Array<ArchitectureComponent>, relationships: Array<ArchitectureRelationship>, };

export type ArchitectureComponent = { id: string, name: string, kind: string, responsibility: string, sources: Array<ArchitectureSource>, parent?: string, provenance: Provenance, evidence: Array<Evidence>, };

export type ArchitectureSource = { node: string, basedOnHash: string, };

export type ArchitectureRelationship = { id: string, from: string, to: string, kind: string, label: string, provenance: Provenance, evidence: Array<Evidence>, };

export type Annotations = { architecture?: Architecture, modules: Array<Module>, descriptions: Array<Description>,
/**
 * Hidden relationships; every one must have `provenance: "ai"` and evidence.
 */
edges: Array<Edge>, entryPoints?: Array<EntryPoint>, flows?: Array<Flow>, };

export type Module = {
/**
 * `module:<slug>`, slug matching `[a-z0-9-]+`.
 */
id: string, name: string, description: string,
/**
 * File node IDs (`file:<relpath>`).
 */
files: Array<string>, };

export type Description = {
/**
 * ID of the described node.
 */
id: string, text: string,
/**
 * The node's `contentHash` when the description was written.
 */
basedOnHash: string, };

export type Report = { schemaVersion: string,
/**
 * Copied from `manifest.json`.
 */
commitSha: string, summary: Summary, elements: Array<ElementStatus>, issues: Array<Issue>, flows?: Array<FlowStatus>, };

export type Summary = { documented: number, stale: number, undocumented: number, errors: number, warnings: number, };

export type ElementStatus = { id: string, status: Status,
/**
 * Set only when `status` is `stale`: a direct child of this element is stale.
 */
childChanged?: boolean,
/**
 * Set only when `status` is `stale`: the element's own text (outside its direct
 * children) changed. See the validator README for how this is determined.
 */
selfChanged?: boolean, };

export type Status = "documented" | "stale" | "undocumented";

export type Issue = { severity: Severity,
/**
 * Stable kebab-case identifier, e.g. `dangling-ref`.
 */
code: string, message: string,
/**
 * The element the issue is about, when there is one.
 */
id?: string, };

export type Severity = "error" | "warning";

export type StructureDiff = { schemaVersion: string,
/**
 * Revision A (the older side), as given or resolved: a full SHA or `worktree`.
 */
fromCommit: string,
/**
 * Revision B (the newer side).
 */
toCommit: string,
/**
 * Every element that is not `unchanged`, plus unchanged containers with changed
 * children (none exist with per-element hashes, but the rule is general).
 */
elements: Array<ElementChange>,
/**
 * Relationships added or removed, keyed by `(from, to, type)` after mapping moved IDs.
 */
edges: Array<EdgeChange>, summary: DiffSummary, };

export type ChangeKind = "added" | "modified" | "moved" | "removed" | "unchanged";

export type ElementChange = {
/**
 * The element's ID in B; for `removed`, its ID in A.
 */
id: string, type: NodeType, change: ChangeKind,
/**
 * For `moved`: the element's ID in A.
 */
movedFrom?: string,
/**
 * Set on `modified` elements (and unchanged containers with changed children): a
 * direct child is added, removed, modified or moved. Same rule as the validator's
 * `childChanged` for stale elements.
 */
childChanged?: boolean, };

export type EdgeChange = {
/**
 * IDs in B; an endpoint that was removed keeps its ID in A.
 */
from: string, to: string, type: EdgeType,
/**
 * `added` or `removed`.
 */
change: ChangeKind, provenance: Provenance,
/**
 * From the side the edge exists on (B for `added`, A for `removed`).
 */
evidence: Evidence, };

export type DiffSummary = { added: number, removed: number, modified: number, moved: number, unchanged: number, edgesAdded: number, edgesRemoved: number, };

export type RepoBundle = {
/**
 * Fresh source/evidence checks; absent in legacy browser bundles.
 */
architectureIssues?: Array<Issue>,
/**
 * Canonical absolute path of the repository root.
 */
root: string, manifest: Manifest, structure: Structure, annotations: Annotations | null, report: Report | null, warnings: Array<AppWarning>, };

export type AppWarning = { code: WarningCode, message: string, };

export type WarningCode = "annotations-missing" | "annotations-invalid" | "report-missing" | "report-invalid" | "report-stale";

export type AppError = { code: ErrorCode, message: string, detail?: string, };

export type ErrorCode = "not-a-directory" | "no-gitvur" | "schema-invalid" | "path-escape" | "io" | "index-failed";

export type SourceSlice = { file: string,
/**
 * Line number of `lines[0]`.
 */
startLine: number, lines: Array<string>, language: SourceLanguage, };

export type SourceLanguage = "c" | "go" | "python" | "typescript" | "text";

export type RecentRepo = { path: string, name: string,
/**
 * Unix time in seconds.
 */
openedAt: number, };

export type Settings = { explorerWidth: number, inspectorWidth: number, inspectorCollapsed: boolean, theme: Theme,
/**
 * The first-run guide was finished or dismissed.
 */
guideSeen: boolean, };

export type Theme = "system" | "light" | "dark";

export type CommitInfo = { sha: string, short: string, subject: string, author: string,
/**
 * Committer time, seconds since the Unix epoch.
 */
date: number, };

export type DiffBundle = { diff: StructureDiff, from: Structure, to: Structure, };

export type ViewState = { activeTab?: string, docPath?: string, docScroll?: number,
/**
 * Flows tab: the selected flow or entry point ID.
 */
flowSelection?: string,
/**
 * Flows tab: `flow` or `trace`.
 */
flowMode?: string, expandedIds: Array<string>,
/**
 * Classes whose rows are folded on the map.
 */
collapsedIds: Array<string>, selectedId?: string, viewport?: Viewport, lens?: string, diffFrom?: string, diffTo?: string, explorerWidth?: number, inspectorWidth?: number, };

export type Viewport = { x: number, y: number, zoom: number, };

export type DocEntry = { path: string, title: string, sizeBytes: number, modified: string, };

export type DocContent = { path: string, text: string, truncated: boolean, };

export type AssetData = { mime: string, dataUrl: string, };
